/**
 * Action 08 Prompt Module for tx-7-imp-1 Agent
 * 
 * This module generates prompts for Action 8 of the tx-7-imp-1 agent workflow.
 * Action 8 is responsible for: 部長に分析レポートを提示する
 * (Presenting the analysis report to the department head)
 * 
 * Part of the monthly report generation workflow:
 * - Trigger confirmation (1st of each month)
 * - Data extraction
 * - Report generation
 * - Time-series analysis
 * - Bottleneck identification
 * - Team performance metrics calculation
 * - Priority assignment
 * - Report presentation to department head
 */

export const ACTION_08_PROMPT_VERSION = "1.0.0";

export interface Action08PromptInput {
  analysisReportData: {
    reportId: string;
    generatedAt: string;
    reportPeriod: {
      startDate: string;
      endDate: string;
    };
    timeSeriesAnalysis: {
      issueCountTrend: Array<{
        date: string;
        count: number;
      }>;
      resolutionTimeTrend: Array<{
        date: string;
        averageDays: number;
      }>;
      categoryDistribution: Record<string, number>;
    };
    bottleneckAnalysis: {
      currentBottlenecks: Array<{
        bottleneckId: string;
        description: string;
        affectedAreas: string[];
        severity: "high" | "medium" | "low";
        trend: "increasing" | "stable" | "decreasing";
      }>;
      bottleneckTransition: Array<{
        period: string;
        activeBottlenecks: string[];
      }>;
    };
    teamPerformanceMetrics: {
      teamId: string;
      teamName: string;
      issueResolutionRate: number;
      averageResolutionTime: number;
      reopenRate: number;
      performanceScore: number;
    }[];
    prioritizedIssues: Array<{
      issueId: string;
      title: string;
      category: string;
      priority: "critical" | "high" | "medium" | "low";
      affectedTeams: string[];
      recommendedAction: string;
    }>;
    anomalies: Array<{
      anomalyType: string;
      description: string;
      severity: "high" | "medium" | "low";
      requiresAttention: boolean;
    }>;
  };
  departmentHeadInfo: {
    name: string;
    email: string;
    department: string;
  };
  presentationContext: {
    meetingDate: string;
    meetingType: "monthly_review" | "quarterly_review" | "ad_hoc";
    previousReportComparison?: {
      previousPeriod: string;
      keyChanges: string[];
    };
  };
}

export interface Action08PromptOutput {
  presentationPrompt: string;
  reportSummary: string;
  keyHighlights: string[];
  recommendedDiscussionPoints: string[];
  escalationItems: Array<{
    itemId: string;
    description: string;
    recommendedAction: string;
    urgency: "immediate" | "urgent" | "normal";
  }>;
  followUpActions: Array<{
    actionId: string;
    description: string;
    owner: string;
    dueDate: string;
  }>;
}

export function buildAction08Prompt(
  input: Action08PromptInput
): Action08PromptOutput {
  const {
    analysisReportData,
    departmentHeadInfo,
    presentationContext,
  } = input;

  // Build key highlights from the analysis
  const keyHighlights: string[] = [];

  // Add time-series trend highlights
  if (analysisReportData.timeSeriesAnalysis.issueCountTrend.length > 0) {
    const trends = analysisReportData.timeSeriesAnalysis.issueCountTrend;
    const firstCount = trends[0].count;
    const lastCount = trends[trends.length - 1].count;
    const trend = lastCount > firstCount ? "増加" : "減少";
    const changePercent = Math.round(
      ((lastCount - firstCount) / firstCount) * 100
    );
    keyHighlights.push(
      `課題件数が${trend}傾向（${changePercent > 0 ? "+" : ""}${changePercent}%）`
    );
  }

  // Add bottleneck highlights
  const highSeverityBottlenecks = analysisReportData.bottleneckAnalysis.currentBottlenecks.filter(
    (b) => b.severity === "high"
  );
  if (highSeverityBottlenecks.length > 0) {
    keyHighlights.push(
      `高優先度のボトルネック: ${highSeverityBottlenecks.length}件`
    );
  }

  // Add team performance highlights
  const topPerformingTeam = analysisReportData.teamPerformanceMetrics.reduce(
    (prev, current) =>
      current.performanceScore > prev.performanceScore ? current : prev
  );
  if (topPerformingTeam) {
    keyHighlights.push(
      `最高パフォーマンスチーム: ${topPerformingTeam.teamName} (スコア: ${topPerformingTeam.performanceScore})`
    );
  }

  // Add anomaly highlights
  const highSeverityAnomalies = analysisReportData.anomalies.filter(
    (a) => a.severity === "high" && a.requiresAttention
  );
  if (highSeverityAnomalies.length > 0) {
    keyHighlights.push(
      `注意が必要な異常値: ${highSeverityAnomalies.length}件`
    );
  }

  // Build recommended discussion points
  const recommendedDiscussionPoints: string[] = [];

  // Add bottleneck discussion points
  analysisReportData.bottleneckAnalysis.currentBottlenecks.forEach((b) => {
    if (b.severity === "high" || b.trend === "increasing") {
      recommendedDiscussionPoints.push(
        `ボトルネック「${b.description}」の対応方針（影響範囲: ${b.affectedAreas.join(", ")}）`
      );
    }
  });

  // Add category-based discussion points
  const topCategories = Object.entries(
    analysisReportData.timeSeriesAnalysis.categoryDistribution
  )
    .sort(([, a], [, b]) => b - a)
    .slice(0, 3);
  topCategories.forEach(([category, count]) => {
    recommendedDiscussionPoints.push(
      `${category}関連の課題が多発（${count}件）- 根本原因の分析と対策`
    );
  });

  // Add team performance discussion points
  const underperformingTeams = analysisReportData.teamPerformanceMetrics.filter(
    (t) => t.performanceScore < 60
  );
  if (underperformingTeams.length > 0) {
    recommendedDiscussionPoints.push(
      `パフォーマンス改善が必要なチーム: ${underperformingTeams.map((t) => t.teamName).join(", ")}`
    );
  }

  // Build escalation items
  const escalationItems = analysisReportData.prioritizedIssues
    .filter((issue) => issue.priority === "critical" || issue.priority === "high")
    .slice(0, 5)
    .map((issue, index) => ({
      itemId: `ESC-${analysisReportData.reportId}-${index + 1}`,
      description: `${issue.title} (影響チーム: ${issue.affectedTeams.join(", ")})`,
      recommendedAction: issue.recommendedAction,
      urgency: issue.priority === "critical" ? "immediate" as const : "urgent" as const,
    }));

  // Add anomaly-based escalation items
  highSeverityAnomalies.forEach((anomaly, index) => {
    escalationItems.push({
      itemId: `ESC-${analysisReportData.reportId}-ANOM-${index + 1}`,
      description: `異常値検出: ${anomaly.description}`,
      recommendedAction: "詳細調査と原因分析が必要",
      urgency: "urgent" as const,
    });
  });

  // Build follow-up actions
  const followUpActions = analysisReportData.prioritizedIssues
    .filter((issue) => issue.priority === "high" || issue.priority === "critical")
    .slice(0, 5)
    .map((issue, index) => {
      const dueDate = new Date();
      dueDate.setDate(dueDate.getDate() + (issue.priority === "critical" ? 1 : 3));
      return {
        actionId: `FA-${analysisReportData.reportId}-${index + 1}`,
        description: `${issue.title}への対応開始`,
        owner: issue.affectedTeams[0] || "未割当",
        dueDate: dueDate.toISOString().split("T")[0],
      };
    });

  // Build report summary
  const reportSummary = `
【${analysisReportData.reportPeriod.startDate}～${analysisReportData.reportPeriod.endDate}の月次分析レポート】

${departmentHeadInfo.name}様

本月次分析レポートは、朝会報告管理システムに蓄積された報告データを自動分析した結果です。

【主要指標】
- 報告課題総数: ${analysisReportData.timeSeriesAnalysis.issueCountTrend.reduce((sum, t) => sum + t.count, 0)}件
- 平均解決期間: ${Math.round(analysisReportData.teamPerformanceMetrics.reduce((sum, t) => sum + t.averageResolutionTime, 0) / analysisReportData.teamPerformanceMetrics.length)}日
- チーム平均パフォーマンススコア: ${Math.round(analysisReportData.teamPerformanceMetrics.reduce((sum, t) => sum + t.performanceScore, 0) / analysisReportData.teamPerformanceMetrics.length)}

【重要な発見】
${keyHighlights.map((h) => `- ${h}`).join("\n")}

【推奨討議事項】
${recommendedDiscussionPoints.slice(0, 5).map((p) => `- ${p}`).join("\n")}

詳細は添付のレポートをご確認ください。
  `.trim();

  // Build presentation prompt
  const presentationPrompt = `
あなたは朝会報告管理システムの分析結果を${departmentHeadInfo.name}部長に提示するAIアシスタントです。

以下の分析レポートを基に、部長が朝会で報告・判断するために必要な情報を整理して提示してください。

【分析期間】${analysisReportData.reportPeriod.startDate}～${analysisReportData.reportPeriod.endDate}

【主要な分析結果】
1. 時系列変化: 課題件数、解決期間の推移を説明
2. ボトルネック推移: 現在のボトルネックと過去の変化パターンを説明
3. チーム別パフォーマンス: 各チームの成績と改善が必要な領域を説明
4. 優先度付き課題: 対応が必要な課題を優先度順に説明

【提示すべき内容】
- 朝会で報告すべき重要な発見
- 即座に対応が必要な課題
- 今月の改善施策の提案
- 次月への改善提案

${presentationContext.previousReportComparison ? `【前月との比較】\n前月の主要な変化: ${presentationContext.previousReportComparison.keyChanges.join(", ")}` : ""}

部長が迅速に判断・指示できるよう、簡潔かつ具体的に提示してください。
  `.trim();

  return {
    presentationPrompt,
    reportSummary,
    keyHighlights,
    recommendedDiscussionPoints,
    escalationItems,
    followUpActions,
  };
}